-- Catálogo de regiões IMOBRART, 05/11/2026.
-- Execute depois de import_imobrart_churches.sql. Preserva IDs e não apaga dados.
begin;
create table if not exists public.church_regions (
 id uuid primary key default gen_random_uuid(),
 number integer not null unique,
 name text not null,
 description text,
 photo_url text,
 source_url text not null unique,
 leadership jsonb not null default '[]'::jsonb,
 source_metadata jsonb,
 updated_at timestamptz not null default now()
);
create table if not exists public.church_region_memberships (
 church_id uuid not null references public.churches(id) on delete cascade,
 region_id uuid not null references public.church_regions(id) on delete cascade,
 source_url text not null,
 primary key(church_id, region_id)
);
alter table public.church_regions enable row level security;
alter table public.church_region_memberships enable row level security;
revoke all on public.church_regions, public.church_region_memberships from public, anon;
grant select, insert, update, delete on public.church_regions, public.church_region_memberships to authenticated;
drop policy if exists regions_read on public.church_regions;
create policy regions_read on public.church_regions for select to authenticated using (true);
drop policy if exists regions_admin on public.church_regions;
create policy regions_admin on public.church_regions for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists region_memberships_read on public.church_region_memberships;
create policy region_memberships_read on public.church_region_memberships for select to authenticated using(true);
drop policy if exists region_memberships_admin on public.church_region_memberships;
create policy region_memberships_admin on public.church_region_memberships for all to authenticated using(public.is_admin()) with check(public.is_admin());

do $import$
declare r jsonb; c jsonb; region_uuid uuid; church_uuid uuid;
begin
 for r in select value from jsonb_array_elements($regions$[{"number": 1, "name": "1ª Região", "source_url": "https://imobrart.org/regioes/1a-regiao/", "description": "A 1ª Região foi a primeira formada por Deus, como modelo a ser seguido. É composta majoritariamente por igrejas em Minas Gerais, que representam cerca de 80% da região. Espírito Santo e Bahia completam a composição, com cerca de 10% cada. Essa região concentra os primeiros trabalhos da Obra e é referência em estrutura, organização e crescimento.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Joezer de Marins Marques", "church_text": "Igreja em Colatina", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-JOEZER.1-225x300.jpg"}, {"role": "Vice-presidente", "name": "Carlos Vieira Duarte", "church_text": "Igreja em Boa Vista de Mantena", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Carlos-Duarte-e1629503761949-181x300.jpeg"}], "churches": [{"name": "Boa Vista de Mantena", "church_source_url": "https://imobrart.org/igrejas/boa-vista/", "catalog_match": true}, {"name": "Braço do Rio", "church_source_url": "https://imobrart.org/igrejas/braco-do-rio/", "catalog_match": true}, {"name": "Colatina", "church_source_url": "https://imobrart.org/igrejas/colatina/", "catalog_match": true}, {"name": "Governador Valadares", "church_source_url": "https://imobrart.org/igrejas/governador-valadares/", "catalog_match": true}, {"name": "Itamarajú", "church_source_url": "https://imobrart.org/igrejas/itamaraju/", "catalog_match": true}, {"name": "Mantena", "church_source_url": "https://imobrart.org/igrejas/mantena/", "catalog_match": true}, {"name": "Padre Paraíso", "church_source_url": "https://imobrart.org/igrejas/padre-paraiso/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 2, "name": "2ª Região", "source_url": "https://imobrart.org/regioes/2a-regiao/", "description": "A 2ª Região da IMOBRART é composta por igrejas localizadas no estado do Rio de Janeiro. Reúne igrejas em Angra dos Reis, nos bairros Bracuí e Japuíba, e também em Parati. Essa região marca a expansão da Obra para o sudeste, consolidando a presença no litoral fluminense.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Anizio de Oliveira Campos", "church_text": "Igreja em Japuíba", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-Anizio-225x300.jpg"}, {"role": "Vice-presidente", "name": "Rogério Teodoro da Silva", "church_text": "Igreja em Bracuí", "photo_url": "https://imobrart.org/wp-content/uploads/2023/01/PASTOR-ROGERIO-1-e1736275423353-287x300.jpg"}], "churches": [{"name": "Bracuí", "church_source_url": "https://imobrart.org/igrejas/bracui/", "catalog_match": true}, {"name": "Japuíba", "church_source_url": "https://imobrart.org/igrejas/japuiba/", "catalog_match": true}, {"name": "Parati", "church_source_url": "https://imobrart.org/igrejas/parati/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 3, "name": "3ª Região", "source_url": "https://imobrart.org/regioes/3a-regiao/", "description": "A 3ª Região da IMOBRART é totalmente formada por igrejas no estado do Rio de Janeiro, com forte presença na capital e na Baixada Fluminense. Inclui bairros como Acari, Anchieta, Cidade de Deus, Inhoaíba, Jardim América, Mendanha, São Mateus e Senador Vasconcelos. É uma região urbana e estratégica, que fortalece a expansão da Obra no Grande Rio.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Erodice Pereira da Silva", "church_text": "Igreja em Cidade de Deus", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-ERON-e1614806222197-205x300.jpg"}, {"role": "Vice-presidente", "name": "Wagner Dias Marques da Silva", "church_text": "Igreja em Vasconcelos", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-WAGNER-MARQUES-225x300.jpg"}], "churches": [{"name": "Acari", "church_source_url": "https://imobrart.org/igrejas/acari/", "catalog_match": true}, {"name": "Anchieta", "church_source_url": "https://imobrart.org/igrejas/anchieta/", "catalog_match": true}, {"name": "Cidade de Deus", "church_source_url": "https://imobrart.org/igrejas/cidade-de-deus/", "catalog_match": true}, {"name": "Inhoaíba", "church_source_url": "https://imobrart.org/igrejas/inhoaiba/", "catalog_match": true}, {"name": "Jardim América", "church_source_url": "https://imobrart.org/igrejas/jardim-america/", "catalog_match": true}, {"name": "Mendanha", "church_source_url": "https://imobrart.org/igrejas/mendanha/", "catalog_match": true}, {"name": "São Mateus", "church_source_url": "https://imobrart.org/igrejas/sao-mateus/", "catalog_match": true}, {"name": "Vasconcelos", "church_source_url": "https://imobrart.org/igrejas/vasconcellos/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 4, "name": "4ª Região", "source_url": "https://imobrart.org/regioes/4a-regiao/", "description": "A 4ª Região da IMOBRART é formada por igrejas no estado do Rio de Janeiro, abrangendo municípios como Nova Iguaçu, Japeri, Seropédica, Paty do Alferes e Vassouras. É uma região marcada pela diversidade urbana e interiorana, com atuação em bairros como Cabuçu, Jardim Aimoré, Jardim Paraíso e Santa Sofia. A expansão nessa região fortalece a presença da Obra na Baixada Fluminense e no interior do estado.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Mauro Sergio de Oliveira", "church_text": "Igreja em Jardim Paraíso", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-MAURO-S-1-e1623275992596-232x300.jpg"}, {"role": "Vice-presidente", "name": "Roberto Reinaldo Campos", "church_text": "Igreja em Cabuçú", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Roberto-Campos-e1613676018270-219x300.jpeg"}], "churches": [{"name": "Arcozelo", "church_source_url": "https://imobrart.org/igrejas/arcozelo/", "catalog_match": true}, {"name": "Cabuçú", "church_source_url": "https://imobrart.org/igrejas/cabucu/", "catalog_match": true}, {"name": "Chaperó", "church_source_url": "https://imobrart.org/igrejas/chapero/", "catalog_match": true}, {"name": "Engenheiro Pedreira", "church_source_url": "https://imobrart.org/igrejas/engenheiro-pedreira/", "catalog_match": true}, {"name": "Jardim Aimoré", "church_source_url": "https://imobrart.org/igrejas/jardim-aimore/", "catalog_match": true}, {"name": "Jardim da Fonte", "church_source_url": "https://imobrart.org/igrejas/jardim-da-fonte/", "catalog_match": true}, {"name": "Jardim Paraíso", "church_source_url": "https://imobrart.org/igrejas/jardim-paraiso/", "catalog_match": true}, {"name": "Ponte Coberta", "church_source_url": "https://imobrart.org/igrejas/ponte-coberta/", "catalog_match": true}, {"name": "Santa Sofia", "church_source_url": "https://imobrart.org/igrejas/santa-sofia/", "catalog_match": true}, {"name": "Três Fontes", "church_source_url": "https://imobrart.org/igrejas/tres-fontes/", "catalog_match": true}, {"name": "Vassouras", "church_source_url": "https://imobrart.org/igrejas/vassouras/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 5, "name": "5ª Região", "source_url": "https://imobrart.org/regioes/5a-regiao/", "description": "A 5ª Região da IMOBRART está localizada na região serrana e metropolitana do Rio de Janeiro. Inclui igrejas em Teresópolis (Araras e Rosário), Duque de Caxias (Imbariê), Petrópolis e Friburgo. É uma região com presença estratégica em áreas urbanas e históricas, fortalecendo a Obra em cidades de grande relevância cultural e populacional.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Marcio de Barros Fuly", "church_text": "Igreja em Parada de Lucas", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-MARCIO-FULY-e1630691497234-192x300.jpg"}, {"role": "Vice-presidente", "name": "Moises de Barros Fuly", "church_text": "Igreja em Araras", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Moises-Fuly-209x300.jpeg"}], "churches": [{"name": "Araras", "church_source_url": "https://imobrart.org/igrejas/araras/", "catalog_match": true}, {"name": "Imbariê", "church_source_url": "https://imobrart.org/igrejas/imbarie/", "catalog_match": true}, {"name": "Parada de Lucas", "church_source_url": "https://imobrart.org/igrejas/parada-de-lucas/", "catalog_match": true}, {"name": "Petrópolis", "church_source_url": "https://imobrart.org/igrejas/petropolis/", "catalog_match": true}, {"name": "Rosário", "church_source_url": "https://imobrart.org/igrejas/rosario/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 6, "name": "6ª Região", "source_url": "https://imobrart.org/regioes/6a-regiao/", "description": "A 6ª Região da IMOBRART abrange igrejas nos estados de São Paulo, Paraná e interior paulista. Conta com unidades em cidades como São Paulo (Jardim Shangri-lá), Ibiúna, Campinas, Nova Luzitânia, Mundo Novo, Paulicéia e Jardim Regina, além de uma congregação no Paraná, em Grandes Rios. Essa região marca a presença da Obra no Sudeste e Sul do país, consolidando a expansão para novos estados e municípios.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Celso Souza Goulart", "church_text": "Igreja em Jardim Shangri-lá", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pr.-CelsoG-e1614140872238-202x300.jpg"}, {"role": "Vice-presidente", "name": "Ubirany de Assis Pereira", "church_text": "Igreja em Ibiúna", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-UBIRANY-225x300.jpg"}], "churches": [{"name": "Campinas", "church_source_url": "https://imobrart.org/igrejas/campinas/", "catalog_match": true}, {"name": "Grandes Rios", "church_source_url": "https://imobrart.org/igrejas/grandes-rios/", "catalog_match": true}, {"name": "Ibiúna", "church_source_url": "https://imobrart.org/igrejas/ibiuna/", "catalog_match": true}, {"name": "Jardim Regina", "church_source_url": "https://imobrart.org/igrejas/jardim-regina/", "catalog_match": true}, {"name": "Jardim Shangri-lá", "church_source_url": "https://imobrart.org/igrejas/jardim-shangri-la/", "catalog_match": true}, {"name": "Mundo Novo", "church_source_url": "https://imobrart.org/igrejas/mundo-novo/", "catalog_match": true}, {"name": "Nova Luzitânia", "church_source_url": "https://imobrart.org/igrejas/nova-luzitania/", "catalog_match": true}, {"name": "Paulicéia", "church_source_url": "https://imobrart.org/igrejas/pauliceia/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 7, "name": "7ª Região", "source_url": "https://imobrart.org/regioes/7a-regiao/", "description": "A 7ª Região da IMOBRART está localizada no Espírito Santo e é formada por igrejas em diversas cidades e distritos do estado. Inclui congregações em Vila Velha, Cariacica, Iúna, Muqui, Irupi, São José de Fruteiras, Córrego Marapé, Ponte do Silva, Pedra Bonita, Brejaubinha, Batatal e Coqueiros. Essa região representa o avanço da Obra na região Sudeste, especialmente no interior capixaba, fortalecendo a presença em áreas rurais e urbanas.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "DANIEL MARQUES SOBRINHO", "church_text": "Igreja em Irupi", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-DANIEL-225x300.jpg"}, {"role": "Vice-presidente", "name": "Samuel da Silva Lino", "church_text": "Igreja em Ponte do Silva", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pr.-Samuel-Lino-193x300.jpeg"}], "churches": [{"name": "Batatal", "church_source_url": "https://imobrart.org/igrejas/batatal/", "catalog_match": true}, {"name": "Bom Jardim", "church_source_url": "https://imobrart.org/igrejas/bom-jardim/", "catalog_match": true}, {"name": "Brejaubinha", "church_source_url": "https://imobrart.org/igrejas/brejaubinha/", "catalog_match": true}, {"name": "Cariacica", "church_source_url": "https://imobrart.org/igrejas/cariacica/", "catalog_match": true}, {"name": "Coqueiros", "church_source_url": "https://imobrart.org/igrejas/coqueiros/", "catalog_match": true}, {"name": "Córrego Marapé (Brejetuba)", "church_source_url": "https://imobrart.org/igrejas/corrego-marape-brejetuba/", "catalog_match": true}, {"name": "Irupi", "church_source_url": "https://imobrart.org/igrejas/irupi/", "catalog_match": true}, {"name": "Iúna", "church_source_url": "https://imobrart.org/igrejas/iuna/", "catalog_match": true}, {"name": "Muqui", "church_source_url": "https://imobrart.org/igrejas/muqui/", "catalog_match": true}, {"name": "Pedra Bonita", "church_source_url": "https://imobrart.org/igrejas/pedra-bonita/", "catalog_match": true}, {"name": "Ponte do Silva", "church_source_url": "https://imobrart.org/igrejas/ponte-do-silva/", "catalog_match": true}, {"name": "São José de Fruteiras", "church_source_url": "https://imobrart.org/igrejas/sao-jose-de-fruteiras/", "catalog_match": true}, {"name": "Vila Velha", "church_source_url": "https://imobrart.org/igrejas/vila-velha/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 8, "name": "8ª Região", "source_url": "https://imobrart.org/regioes/8a-regiao/", "description": "A 8ª Região da IMOBRART abrange igrejas no Nordeste do Brasil, com presença nos estados da Bahia e do Ceará. Estão incluídas as cidades de Capim Grosso (BA), Horizonte, Chorozinho, Pacajús e Lagoa do Cedro (CE). Essa região representa o avanço da Obra em território nordestino, alcançando comunidades com forte identidade local e grande receptividade à mensagem do Reino.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Misael Jacinto de Souza", "church_text": "Igreja em Pacajús", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-MISAEL-e1630706725192-186x300.jpg"}, {"role": "Vice-presidente", "name": "Laerte Garcia Vidal", "church_text": "Igreja em Capim Grosso", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Laerte--221x300.jpeg"}], "churches": [{"name": "Capim Grosso", "church_source_url": "https://imobrart.org/igrejas/capim-grosso/", "catalog_match": true}, {"name": "Chorozinho", "church_source_url": "https://imobrart.org/igrejas/chorozinho/", "catalog_match": true}, {"name": "Horizonte", "church_source_url": "https://imobrart.org/igrejas/horizonte/", "catalog_match": true}, {"name": "Lagoa do Cedro", "church_source_url": "https://imobrart.org/igrejas/lagoa-do-cedro/", "catalog_match": true}, {"name": "Pacajús", "church_source_url": "https://imobrart.org/igrejas/pacajus/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 9, "name": "9ª Região", "source_url": "https://imobrart.org/regioes/9a-regiao/", "description": "A 9ª Região da IMOBRART é formada exclusivamente por igrejas localizadas no estado de Minas Gerais. Inclui congregações em Cataguases, Santos Dumont, Caxambu, Balneário e Venda Nova. Essa região fortalece ainda mais a atuação da Obra em território mineiro, com presença em cidades estratégicas do interior.", "photo_url": null, "leadership": [{"role": "Presidente", "name": "Emanuel de Souza", "church_text": null, "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/PR.-EMANOEL-1-e1627169345363-183x300.jpg"}], "churches": [{"name": "Balneário", "church_source_url": "https://imobrart.org/igrejas/balneario/", "catalog_match": true}, {"name": "Cataguases", "church_source_url": "https://imobrart.org/igrejas/cataguases/", "catalog_match": true}, {"name": "Caxambú", "church_source_url": "https://imobrart.org/igrejas/caxambu/", "catalog_match": true}, {"name": "Santos Dumont", "church_source_url": "https://imobrart.org/igrejas/santos-dumont/", "catalog_match": true}, {"name": "Venda Nova", "church_source_url": "https://imobrart.org/igrejas/venda-nova/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 10, "name": "10ª Região", "source_url": "https://imobrart.org/regioes/10a-regiao/", "description": "A 10ª Região da IMOBRART está situada na Baixada Fluminense, no estado do Rio de Janeiro. Composta por igrejas localizadas em Belford Roxo e São João de Meriti, reúne bairros como Jardim Redentor, Parque da Flores, Jardim Olavo Bilac, Andrade Araújo, Parque Novo Rio, Pilar, São Judas Tadeu e Três Corações. Essa região reforça a presença da Obra em áreas densamente povoadas e de grande relevância social.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Uziel Flor Henrique", "church_text": "Igreja em Jardim Olavo Bilac", "photo_url": "https://imobrart.org/wp-content/uploads/2023/01/Pastor-Uziel-e1673123848444-286x300.jpg"}, {"role": "Vice-presidente", "name": "Isaac Diniz", "church_text": "Igreja em Jardim Olavo Bilac", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Isaac-e1614136072687.jpeg"}], "churches": [{"name": "Andrade Araújo", "church_source_url": "https://imobrart.org/igrejas/andrade-araujo/", "catalog_match": true}, {"name": "Jardim Olavo Bilac", "church_source_url": "https://imobrart.org/igrejas/jardim-olavo-bilac/", "catalog_match": true}, {"name": "Jardim Redentor", "church_source_url": "https://imobrart.org/igrejas/jardim-redentor/", "catalog_match": true}, {"name": "Parque da Flores (Santa Marta)", "church_source_url": "https://imobrart.org/igrejas/parque-da-flores-santa-marta/", "catalog_match": true}, {"name": "Parque Novo Rio", "church_source_url": "https://imobrart.org/igrejas/parque-novo-rio/", "catalog_match": true}, {"name": "Pilar", "church_source_url": "https://imobrart.org/igrejas/pilar/", "catalog_match": true}, {"name": "São Judas Tadeu", "church_source_url": "https://imobrart.org/igrejas/sao-judas-tadeu/", "catalog_match": true}, {"name": "Três Corações", "church_source_url": "https://imobrart.org/igrejas/tres-coracoes/", "catalog_match": true}], "retrieved_at": "2026-11-05"}, {"number": 11, "name": "11ª Região", "source_url": "https://imobrart.org/regioes/11a-regiao/", "description": "A 11ª Região da IMOBRART está localizada no estado do Rio de Janeiro e reúne igrejas em cidades da região metropolitana e do interior. As congregações estão presentes em Magé, São Pedro da Aldeia, Parque Ribeira, Jardim Alcântara, Jardim Catarina, Barreto e Bom Jardim. Essa região amplia o alcance da Obra nas áreas litorâneas e urbanas do estado.", "photo_url": "https://imobrart.org/wp-content/uploads/2025/03/sobre.png", "leadership": [{"role": "Presidente", "name": "Jonas Lima da Silva", "church_text": "Igreja em Parque Ribeira", "photo_url": "https://imobrart.org/wp-content/uploads/2022/07/WhatsApp-Image-2022-07-21-at-11.18.46-1-e1658415703505-264x300.jpeg"}, {"role": "Vice-presidente", "name": "Valter Sérgio de Araujo", "church_text": "Igreja em Jardim Catarina", "photo_url": "https://imobrart.org/wp-content/uploads/2021/01/Pastor-Valter-Sergio-e1666227367761-210x300.jpg"}], "churches": [{"name": "Barreto", "church_source_url": "https://imobrart.org/igrejas/barreto/", "catalog_match": true}, {"name": "Friburgo", "church_source_url": "https://imobrart.org/igrejas/friburgo/", "catalog_match": true}, {"name": "Jardim Alcântara", "church_source_url": "https://imobrart.org/igrejas/jardim-alcantara/", "catalog_match": true}, {"name": "Jardim Catarina", "church_source_url": "https://imobrart.org/igrejas/jardim-catarina/", "catalog_match": true}, {"name": "Magé", "church_source_url": "https://imobrart.org/igrejas/mage/", "catalog_match": true}, {"name": "Parque Ribeira", "church_source_url": "https://imobrart.org/igrejas/parque-ribeira/", "catalog_match": true}, {"name": "São Pedro da Aldeia", "church_source_url": "https://imobrart.org/igrejas/sao-pedro-da-aldeia/", "catalog_match": true}], "retrieved_at": "2026-11-05"}]$regions$::jsonb)
 loop
  insert into public.church_regions(number,name,description,photo_url,source_url,leadership,source_metadata)
  values((r->>'number')::integer,r->>'name',r->>'description',r->>'photo_url',r->>'source_url',r->'leadership',r)
  on conflict(source_url) do update set name=excluded.name,description=excluded.description,photo_url=excluded.photo_url,leadership=excluded.leadership,source_metadata=excluded.source_metadata,updated_at=now()
  returning id into region_uuid;
  for c in select value from jsonb_array_elements(r->'churches')
  loop
   select id into church_uuid from public.churches where source_url=c->>'church_source_url';
   if church_uuid is null then raise exception 'Igreja não importada: %. Execute antes a importação de igrejas.',c->>'church_source_url'; end if;
   insert into public.church_region_memberships(church_id,region_id,source_url)
   values(church_uuid,region_uuid,r->>'source_url')
   on conflict(church_id,region_id) do update set source_url=excluded.source_url;
  end loop;
 end loop;
end;
$import$;
commit;
notify pgrst, 'reload schema';

-- Conferência: 11 regiões e 80 vínculos desta coleta.
select r.number,r.name,count(m.church_id) as churches
from public.church_regions r left join public.church_region_memberships m on m.region_id=r.id
group by r.id order by r.number;
